def start():
    print("You wake up in a train station.")
    print("Go north to the plaza, or east to the cafe?")
    choice = input("> ").strip().lower()
    if choice == "north":
        return "plaza"
    if choice == "east":
        return "cafe"
    print("Confused, you stay put.")
    return "start"


def plaza():
    print("A fountain sparkles. You find a ticket. You win!")
    return "end"


def cafe():
    print("Coffee smell. You rest, then head back.")
    return "start"


SCENES = {
    "start": start,
    "plaza": plaza,
    "cafe": cafe,
}

room = "start"
while room != "end":
    room = SCENES[room]()
print("--- thanks for playing ---")
